-- Private multi-market projection. Existing orders and history retain their origin.
create table public.rh20_markets (
 address text primary key check(address ~ '^0x[0-9a-f]{40}$'),
 deployment_block bigint not null check(deployment_block>0),
 runtime text not null check(runtime ~ '^0x[0-9a-f]+$')
);
alter table public.rh20_markets enable row level security;
revoke all on public.rh20_markets from public,anon,authenticated;
grant select,insert,update,delete on public.rh20_markets to service_role;
insert into public.rh20_markets values('0x3e6e91232ce0895c6154b66800ee5c8b8ee83cfc',75378393,'');
alter table public.rh20_holder_orders add column marketplace text not null default '0x3e6e91232ce0895c6154b66800ee5c8b8ee83cfc' references public.rh20_markets(address);
alter table public.rh20_holder_orders drop constraint rh20_holder_orders_pkey;
alter table public.rh20_holder_orders add primary key(marketplace,listing_id);
create index rh20_multi_market_unit_price on public.rh20_holder_orders(marketplace,(price::numeric(110,30)/amount),listing_id) where state=1;
create or replace function public.rh20_holder_delta(p_account text,p_liquid bigint,p_listed bigint)
returns void language plpgsql security invoker set search_path = '' as $$
declare before_total bigint; after_total bigint; eligible boolean;
begin
  if p_account='0x0000000000000000000000000000000000000000' then return; end if;
  insert into public.rh20_holder_balances(account) values(p_account) on conflict do nothing;
  select liquid+listed into strict before_total from public.rh20_holder_balances where account=p_account for update;
  update public.rh20_holder_balances set liquid=liquid+p_liquid,listed=listed+p_listed where account=p_account returning liquid+listed into after_total;
  eligible:=not exists(select 1 from public.rh20_markets where address=p_account);
  if eligible and ((before_total>0)<>(after_total>0)) then
    update public.rh20_holder_state set computed_holders=computed_holders+case when after_total>0 then 1 else -1 end where id;
  end if;
end $$;
create or replace function public.rh20_holder_event(p_event jsonb,p_reverse boolean default false)
returns boolean language plpgsql security invoker set search_path = '' as $$
declare market text:=coalesce(p_event->>'market','0x3e6e91232ce0895c6154b66800ee5c8b8ee83cfc'); k text:=p_event->>'kind'; n bigint; listing bigint; row_data public.rh20_holder_orders%rowtype; factor integer:=case when p_reverse then -1 else 1 end;
begin
  if k='transfer' then
    n:=(p_event->>'amount')::bigint;
    if n<=0 or n>21000000 then raise exception 'Invalid transfer amount'; end if;
    if not p_reverse then
      perform public.rh20_holder_delta(p_event->>'from',-n,0);
      perform public.rh20_holder_delta(p_event->>'to',n,0);
    else
      perform public.rh20_holder_delta(p_event->>'to',-n,0);
      perform public.rh20_holder_delta(p_event->>'from',n,0);
    end if;
  elsif k='listed' then
    listing:=(p_event->>'id')::bigint; n:=(p_event->>'amount')::bigint;
    if p_reverse then
      select * into strict row_data from public.rh20_holder_orders where marketplace=market and listing_id=listing;
      if row_data.state<>1 or row_data.seller<>p_event->>'seller' or row_data.amount<>n then raise exception 'Invalid listing undo'; end if;
      delete from public.rh20_holder_orders where marketplace=market and listing_id=listing;
    else
      if (p_event->>'price') is null then raise exception 'Missing canonical listing price'; end if;
      insert into public.rh20_holder_orders(marketplace,listing_id,seller,amount,state,price) values(market,listing,p_event->>'seller',n,1,(p_event->>'price')::numeric);
    end if;
    perform public.rh20_holder_delta(p_event->>'seller',0,n*factor);
  elsif k in ('bought','cancelled') then
    listing:=(p_event->>'id')::bigint;
    select * into row_data from public.rh20_holder_orders where marketplace=market and listing_id=listing for update;
    if not found and k='cancelled' then return false; end if; -- another ticker
    if not found then raise exception 'Missing RHSC listing'; end if;
    if k='cancelled' and row_data.seller<>p_event->>'seller' then raise exception 'Cancellation seller differs'; end if;
    if (not p_reverse and row_data.state<>1) or (p_reverse and row_data.state<>case when k='bought' then 2 else 3 end) then raise exception 'Invalid listing state'; end if;
    if k='bought' and row_data.amount<>(p_event->>'amount')::bigint then raise exception 'Purchase amount differs'; end if;
    perform public.rh20_holder_delta(row_data.seller,0,-row_data.amount*factor);
    update public.rh20_holder_orders set state=case when p_reverse then 1 when k='bought' then 2 else 3 end where marketplace=market and listing_id=listing;
  else raise exception 'Unknown holder event'; end if;
  return true;
end $$;
create or replace function public.rh20_holders_acquire(p_lease uuid)
returns jsonb language plpgsql security invoker set search_path = '' as $$
declare s public.rh20_holder_state%rowtype; checkpoints jsonb;
begin
  select * into strict s from public.rh20_holder_state where id for update;
  if s.lease_until>now() or s.last_started_at>now()-interval '15 seconds' then return null; end if;
  update public.rh20_holder_state set lease_id=p_lease,lease_until=now()+interval '90 seconds',last_started_at=now() where id;
  select coalesce(jsonb_agg(x order by block_number desc),'[]'::jsonb) into checkpoints from (select * from public.rh20_holder_checkpoints order by block_number desc limit 16) x;
  return jsonb_build_object('cursor',s.cursor_block,'hash',s.cursor_hash,'start',s.start_block,'checkpoints',checkpoints,'markets',(select jsonb_agg(jsonb_build_object('contractAddress',address,'deploymentBlock',deployment_block,'marketRuntime',runtime) order by deployment_block,address) from public.rh20_markets));
end $$;
create or replace function public.rh20_market_board_for(p_market text,p_offset integer default 0,p_limit integer default 12)
returns jsonb language plpgsql stable security invoker set search_path = '' as $$
declare result jsonb; s public.rh20_holder_state%rowtype;
begin
  if p_offset<0 or p_offset>1000000 or p_limit<1 or p_limit>12 then raise exception 'Invalid market page'; end if;
  p_market:=lower(p_market);
  if not exists(select 1 from public.rh20_markets where address=p_market) then raise exception 'Unknown market'; end if;
  select * into strict s from public.rh20_holder_state where id;
  select coalesce(jsonb_agg(q.listing_id::text order by q.unit_price,q.listing_id),'[]'::jsonb) into result
    from (select listing_id,price::numeric(110,30)/amount as unit_price from public.rh20_holder_orders where state=1 and marketplace=p_market order by price::numeric(110,30)/amount,listing_id offset p_offset limit p_limit) q;
  return jsonb_build_object('chainId',4663,'ticker','RHSC','marketplaceAddress',p_market,'sort','unit-price-asc','ids',result,'offset',p_offset,'total',(select count(*) from public.rh20_holder_orders where state=1 and marketplace=p_market),'blockNumber',s.cursor_block,'updatedAt',s.published_at,'status',case when s.published_at<now()-interval '90 seconds' then 'delayed' else s.status end);
end $$;
create or replace function public.rh20_market_board(p_offset integer default 0,p_limit integer default 12)
returns jsonb language sql stable security invoker set search_path='' as $$
 select public.rh20_market_board_for('0x3e6e91232ce0895c6154b66800ee5c8b8ee83cfc',p_offset,p_limit)
$$;
create or replace function public.rh20_holders_snapshot()
returns jsonb language sql stable security invoker set search_path = '' as $$
  select jsonb_build_object('ticker','RHSC','chainId',4663,'coreAddress','0x4e89Bc6A7A218B338060d428f40d8f551efc8058','marketplaceAddress','0x3E6E91232CE0895C6154b66800ee5c8B8EE83CFC',
    'marketplaceAddresses',(select jsonb_agg(address order by deployment_block,address) from public.rh20_markets),'holders',published_holders,'blockNumber',published_block,'updatedAt',published_at,'status',case when published_at<now()-interval '90 seconds' then 'delayed' else status end,
    'definition','unique owners including listed RHSC','refreshSeconds',20)
  from public.rh20_holder_state where id
$$;
-- Call only after canonical deployment and exact runtime verification.
create function public.rh20_register_market(p_address text,p_block bigint,p_runtime text)
returns void language plpgsql security invoker set search_path='' as $$
declare existing public.rh20_markets%rowtype;
begin
 perform 1 from public.rh20_holder_state where id for update;
 p_address:=lower(p_address);
 select * into existing from public.rh20_markets where address=p_address;
 if found then
  if existing.deployment_block<>p_block or existing.runtime<>p_runtime then raise exception 'Pinned market differs'; end if;
  return;
 end if;
 if (select count(*) from public.rh20_markets)>=2 then raise exception 'Only the approved previous and holder marketplaces are supported'; end if;
 insert into public.rh20_markets values(p_address,p_block,p_runtime);
 -- Keep the last published count while replaying any events before registration.
 delete from public.rh20_holder_events; delete from public.rh20_holder_checkpoints;
 delete from public.rh20_holder_orders; delete from public.rh20_holder_balances;
 update public.rh20_holder_state set cursor_block=start_block-1,cursor_hash=null,computed_holders=0,status='indexing',lease_id=null,lease_until=null,last_started_at=null where id;
end $$;
revoke all on function public.rh20_market_board_for(text,integer,integer),public.rh20_register_market(text,bigint,text) from public,anon,authenticated;
grant execute on function public.rh20_market_board_for(text,integer,integer),public.rh20_register_market(text,bigint,text) to service_role;
